package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct { // 01 DISC-REC, 15 bytes
	DrItem string // PIC X(6) @0 len=6
	DrPrice decimal.Decimal // PIC 9(5)V99 @6 len=7
	DrPct int64 // PIC 9(2) @13 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                     // PIC X len=1 = "N"
var WsDiscount decimal.Decimal // PIC 9(5)V99 len=7 = 0
var WsNet decimal.Decimal // PIC 9(5)V99 len=7 = 0
var WsTotalNet decimal.Decimal // PIC 9(8)V99 len=10 = 0
var WsCount int64 // PIC 9(3) len=3 = 0
var WsPriceEd string // PIC ZZ,ZZ9.99 len=9
var WsDiscEd string // PIC ZZ,ZZ9.99 len=9
var WsNetEd string // PIC ZZ,ZZ9.99 len=9
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13

// additional working storage for file handling
var CurDiscRec DiscRec
var discFile *os.File
var discScanner *bufio.Scanner

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func parsePrice(s string) decimal.Decimal {
	// s length 7, digits only, implied V99
	// treat spaces as zero
	filtered := ""
	for _, c := range s {
		if c >= '0' && c <= '9' {
			filtered += string(c)
		}
	}
	if filtered == "" {
		return decimal.Zero
	}
	// remove leading spaces already
	d, err := decimal.NewFromString(filtered)
	if err != nil {
		return decimal.Zero
	}
	return d.Shift(-2)
}

func parsePct(s string) int64 {
	filtered := ""
	for _, c := range s {
		if c >= '0' && c <= '9' {
			filtered += string(c)
		}
	}
	if filtered == "" {
		return 0
	}
	d, err := decimal.NewFromString(filtered)
	if err != nil {
		return 0
	}
	v := d.IntPart()
	if v < 0 {
		v = -v
	}
	v = v % 100
	return v
}

func storeDecimal(val decimal.Decimal, intDigits, scale int, rounded bool) decimal.Decimal {
	var q decimal.Decimal
	if rounded {
		q = val.Round(int32(scale))
	} else {
		q = val.Truncate(int32(scale))
	}
	totalDigits := intDigits + scale
	divisor := decimal.New(1, int32(totalDigits))
	scaled := q.Shift(int32(scale))
	rem := scaled.Mod(divisor)
	result := rem.Shift(int32(-scale))
	return result
}

func storeInt(val int64, digits int) int64 {
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if val >= 0 {
		return val % mod
	}
	return -((-val) % mod)
}

func formatUneditedInt(val int64, digits int) string {
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	v := val
	if v < 0 {
		v = -v
		v = v % mod
	} else {
		v = v % mod
	}
	return fmt.Sprintf("%0*d", digits, v)
}

func formatEdited(val decimal.Decimal, picture string) string {
	dotIdx := strings.Index(picture, ".")
	intDigits := 0
	scale := 0
	if dotIdx >= 0 {
		for i := 0; i < dotIdx; i++ {
			if picture[i] == 'Z' || picture[i] == '9' {
				intDigits++
			}
		}
		for i := dotIdx + 1; i < len(picture); i++ {
			if picture[i] == 'Z' || picture[i] == '9' {
				scale++
			}
		}
	} else {
		for i := 0; i < len(picture); i++ {
			if picture[i] == 'Z' || picture[i] == '9' {
				intDigits++
			}
		}
	}

	q := val.Truncate(int32(scale))
	isNeg := q.IsNegative()
	absQ := q.Abs()

	totalDigits := intDigits + scale
	divisor := decimal.New(1, int32(totalDigits))
	scaledAbs := absQ.Shift(int32(scale))
	scaledAbs = scaledAbs.Truncate(0)
	rem := scaledAbs.Mod(divisor)

	remStr := rem.StringFixed(0)
	// rem is non-negative
	if len(remStr) < totalDigits {
		remStr = strings.Repeat("0", totalDigits-len(remStr)) + remStr
	} else if len(remStr) > totalDigits {
		remStr = remStr[len(remStr)-totalDigits:]
	}

	intPartStr := ""
	fracPartStr := ""
	if intDigits > 0 {
		intPartStr = remStr[:intDigits]
	}
	if scale > 0 {
		fracPartStr = remStr[intDigits:]
	}

	result := []rune(picture)

	// fill integer part
	if dotIdx >= 0 {
		intIdx := 0
		for i := 0; i < dotIdx; i++ {
			if picture[i] == 'Z' || picture[i] == '9' {
				if intIdx < len(intPartStr) {
					result[i] = rune(intPartStr[intIdx])
					intIdx++
				}
			}
		}
		fracIdx := 0
		for i := dotIdx + 1; i < len(picture); i++ {
			if picture[i] == 'Z' || picture[i] == '9' {
				if fracIdx < len(fracPartStr) {
					result[i] = rune(fracPartStr[fracIdx])
					fracIdx++
				}
			}
		}
	} else {
		intIdx := 0
		for i := 0; i < len(picture); i++ {
			if picture[i] == 'Z' || picture[i] == '9' {
				if intIdx < len(intPartStr) {
					result[i] = rune(intPartStr[intIdx])
					intIdx++
				}
			}
		}
	}

	// collect integer placeholder positions
	var intPositions []int
	if dotIdx >= 0 {
		for i := 0; i < dotIdx; i++ {
			if picture[i] == 'Z' || picture[i] == '9' {
				intPositions = append(intPositions, i)
			}
		}
	} else {
		for i := 0; i < len(picture); i++ {
			if picture[i] == 'Z' || picture[i] == '9' {
				intPositions = append(intPositions, i)
			}
		}
	}

	suppressing := true
	for _, pos := range intPositions {
		picChar := picture[pos]
		digitChar := result[pos]
		if picChar == 'Z' {
			if suppressing && digitChar == '0' {
				result[pos] = ' '
			} else {
				suppressing = false
			}
		} else { // '9'
			suppressing = false
		}
	}

	// comma handling
	for i := 0; i < len(picture); i++ {
		if picture[i] == ',' {
			allSpaces := true
			for _, pos := range intPositions {
				if pos < i {
					if result[pos] != ' ' {
						allSpaces = false
						break
					}
				}
			}
			if allSpaces {
				result[i] = ' '
			}
		}
	}

	// sign handling (if negative, place minus before first digit)
	if isNeg && !q.IsZero() {
		firstDigitIdx := -1
		for i, r := range result {
			if r != ' ' && r != ',' && r != '.' {
				firstDigitIdx = i
				break
			}
		}
		if firstDigitIdx != -1 {
			placed := false
			for i := firstDigitIdx - 1; i >= 0; i-- {
				if result[i] == ' ' {
					result[i] = '-'
					placed = true
					break
				}
			}
			if !placed && len(result) > 0 {
				result[0] = '-'
			}
		}
	}

	return string(result)
}

func ReadPara() {
	if discScanner == nil {
		WsEofFlag = "Y"
		return
	}
	if discScanner.Scan() {
		line := discScanner.Text()
		if len(line) < 15 {
			line = line + strings.Repeat(" ", 15-len(line))
		} else if len(line) > 15 {
			line = line[:15]
		}
		CurDiscRec.DrItem = line[0:6]
		priceStr := line[6:13]
		pctStr := line[13:15]
		CurDiscRec.DrPrice = parsePrice(priceStr)
		CurDiscRec.DrPct = parsePct(pctStr)
	} else {
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	// COMPUTE WS-DISCOUNT ROUNDED = DR-PRICE * DR-PCT / 100
	pctDec := decimal.NewFromInt(CurDiscRec.DrPct)
	computed := CurDiscRec.DrPrice.Mul(pctDec).Shift(-2)
	WsDiscount = storeDecimal(computed, 5, 2, true)

	// COMPUTE WS-NET = DR-PRICE - WS-DISCOUNT
	netRaw := CurDiscRec.DrPrice.Sub(WsDiscount)
	WsNet = storeDecimal(netRaw, 5, 2, false)

	// ADD WS-NET TO WS-TOTAL-NET
	totalRaw := WsTotalNet.Add(WsNet)
	WsTotalNet = storeDecimal(totalRaw, 8, 2, false)

	// ADD 1 TO WS-COUNT
	WsCount = storeInt(WsCount+1, 3)

	// MOVE to edited
	WsPriceEd = formatEdited(CurDiscRec.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")

	pctEd := formatUneditedInt(CurDiscRec.DrPct, 2)
	fmt.Printf("%s %s %s%% %s %s\n", CurDiscRec.DrItem, WsPriceEd, pctEd, WsDiscEd, WsNetEd)

	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	cntEd := formatUneditedInt(WsCount, 3)
	fmt.Printf("ITEMS: %s NET TOTAL: %s\n", cntEd, WsTotalEd)
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty but report error as per spec
		fmt.Fprintf(os.Stderr, "failed to open input.dat: %v\n", err)
		os.Exit(1)
	}
	discFile = f
	defer discFile.Close()
	discScanner = bufio.NewScanner(f)
	// allow large lines (though 15 bytes is tiny)
	buf := make([]byte, 0, 64*1024)
	discScanner.Buffer(buf, 1024*1024)

	WsEofFlag = "N"
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	SummaryPara()
}

func main() {
	MainPara()
}
